  name?: string;
  // Absolute local JSON file path
  outputPath: string;
  // Absolute local JSON file path
  path: string;
  scaleToMm?: number;
}): Promise<CallToolResult>; };
```

Validate a saved parsed print JSON and return compact metadata or a bounded segments/triangles page (maximum 200). Coordinates use mm; layerIndex is a zero-based layer filter. Optional exact revision prevents stale reads.

exec tool declaration:
```ts
declare const tools: { mcp__airpocket_studio__studio_inspect_print(args: {
  expectedRevision?: string;
  kind?: "segments" | "triangles";
  layerIndex?: number;
  limit?: number;
  offset?: number;
  // Absolute local JSON file path
  path: string;
  viewId?: string;
}): Promise<CallToolResult>; };
```

Inspect physical input, unit, execution, provenance and selected observation declarations without running solvers. Strict quantitative/exploratory provenance covers static isotropic/orthotropic structure, isotropic modal and temperature-evaluated/thermal-stress structure, small-strain J2 and Neo-Hookean structure, thermal conduction, acoustics and limited channel/exterior Stokes flow within their implemented combinations. Returns required input pointers and remaining mesh/constraint/accuracy checks; allowed is not a physical accuracy guarantee. Includes actual Node host metadata and observed-risk diagnostics, not runtime safety certification.

exec tool declaration:
```ts
declare const tools: { mcp__airpocket_studio__studio_preflight_project(args: {
  adaptive?: boolean;
  includeFields?: boolean;
  method?: "wasm-pcg" | "pcg" | "pcg-strict" | "mfem-wasm";
  mode?: "legacy" | "quantitative" | "exploratory";
  operation?: "solve" | "mesh";
  // Absolute local JSON file path
  path: string;
}): Promise<CallToolResult>; };
```

Preview STEP CAD replacement without modifying files. Requires the current project revision. Replacement is an absolute STEP/STP (OCCT normalizes to mm) or saved STEP project JSON. Returns replacement revision and bounded condition reports (maximum 50), never full geometry.

exec tool declaration:
```ts
declare const tools: { mcp__airpocket_studio__studio_preview_cad_update(args: {
  expectedRevision: string;
  limit?: number;
  offset?: number;
  // Absolute local JSON file path
  path: string;
  // Absolute local JSON file path
  replacementPath: string;
}): Promise<CallToolResult>; };
```

Preview semantic input edits without writing files or changing a browser. Returns the exact resulting input revision, bounded changed JSON pointers, compact summary and Node physical preflight. A valid edit can return preflight.allowed false with missing-input diagnostics. Nested operation payloads remain validated by the actual semantic methods; no physical input is inferred.

exec tool declaration:
```ts
declare const tools: { mcp__airpocket_studio__studio_preview_edit(args: {
  expectedRevision: string;
  method?: "wasm-pcg" | "pcg" | "pcg-strict" | "mfem-wasm";
  mode?: "legacy" | "quantitative" | "exploratory";
  operation?: "solve" | "mesh";
  operations: Array<{
  // Positional arguments of the selected semantic method; nested material, boundary and provenance validation is runtime-only.
  args: Array<string>;
  method: "selectTriangles" | "selectCadFace" | "selectPlanarRegion" | "selectCylindricalRegion" | "clearSelection" | "addCondition" | "removeCondition" | "selectCondition" | "replaceConditionRegion" | "reapplyConditionRegion" | "setMaterial" | "setMaterialProperties" | "setMaterialPreset" | "applyCatalogMaterial" | "setStudy" | "setMeshSettings" | "setInputProvenance" | "setAnalysisIntent";
}>;
  // Absolute local JSON file path
  path: string;
  size?: number;
}): Promise<CallToolResult>; };
```

Measure a saved analysis at a point in mm. Use bodyIndex or elementIndex to select ambiguous multi-body interface points. Returns physical units and the verified saved analysisAssessment when available; no extrapolation outside the mesh.

exec tool declaration:
```ts
declare const tools: { mcp__airpocket_studio__studio_probe(args: {
  bodyIndex?: number;
  elementIndex?: number;
  modeIndex?: number;
  // Absolute local JSON file path
  path: string;
  point: Array<number>;
}): Promise<CallToolResult>; };
```

Start a local CPU analysis job and immediately return its job ID and frozen input revision. Poll studio_job_events for bounded intermediate summaries. requestId makes retries idempotent while the job is retained. Optional includeFields writes provisional meshes, scalar time fields and supported converged nonlinear load-step displacement fields beside outputPath. Does not change the browser.

